Statement 11457:
-------------------------------------------------------------------------------
select
                                    (vendaliquida - sangria - transferencia + suprimento + recebimentos) totalcaixa

                                    from(

                                    select
                                            sum(sangria) sangria,
                                            sum(suprimento) suprimento,
                                            sum(transferencia) transferencia,
                                            sum(recebimentos) recebimentos,
                                            sum(vendaliquida) vendaliquida
        
                                            from(
        
                                            select
                                                (valorsaida) as sangria,
                                                0 suprimento,
                                                0 transferencia,
                                                0 recebimentos,
                                                0 vendaliquida,
                                                cast(datahoracadastro as date) data,
                                                Cast(datahoracadastro as time) horario,
                                                tca.codfuncionario codfuncionario,
                                                tca.centrocusto centrocusto
                                            from
                                                tcaixa tca
                                            where
                                                origem = 'SANGRIA NFCE'
            
                                            union all
            
                                            select
                                                0 sangria,
                                                (valorentrada) as suprimento,
                                                0 transferencia,
                                                0 recebimentos,
                                                0 vendaliquida,
                                                cast(datahoracadastro as date) data,
                                                Cast(datahoracadastro as time) horario,
                                                tca.codfuncionario codfuncionario,
                                                tca.centrocusto centrocusto
                                            from
                                                tcaixa tca
                                            where
                                                origem = 'SUPRIMENTO NFCE'
            
                                            union all
            
                                            select
                                                0 sangria,
                                                0 suprimento,
                                                0 as transferencia,
                                                0 recebimentos,
                                                0 vendaliquida,
                                                cast(datahoracadastro as date) data,
                                                Cast(datahoracadastro as time) horario,
                                                codfuncionario codfuncionario,
                                                centrocusto centrocusto
                                            from
                                                tcaixa                                                                    
            
                                            union all
            
                                            select
                                            0 sangria,
                                            0 suprimento,
                                            0 transferencia,
                                            (valorentrada - valorsaida) as recebimentos,
                                            0 vendaliquida,
                                            Cast(datahoracadastro as date) data,
                                            Cast(datahoracadastro as time) horario,
                                            codfuncionario codfuncionario,
                                            centrocusto centrocusto
            
                                        from tcaixa
            
                                        where
                                            codreceber IS NOT NULL
                                            and (origem not like '%SANGRIA%') AND (origem not like '%SUPRIMENTO%')
            
                                        union all
            
                                        Select
                                            0 sangria,
                                            0 suprimento,
                                            0 transferencia,
                                            0 recebimentos,
                                            coalesce((valortotalnfce), 0) as vendaliquida,
                                            nfce.dataemissao data ,
