select
                            sum(vendabruta + vendabrutanfce) vendabruta,
                            sum(canceladas + canceladasnfce) canceladas,
                            sum(descontos + descontosnfce) descontos,
                            sum(acrescimos + acrescimosnfce) acrescimos,
                            sum(recebimentos) recebimentos,
                            sum(taxaservico) taxaservico,
                            sum(vendaliquida + vendaliquidanfce) vendaliquida

                            from(

                    select
                        nm.totalbruto vendabruta,
                        0 vendabrutanfce,
                        0 canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        0 acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm
                        

                union all

                select
                        0 vendabruta,
                        0 vendabrutanfce,
                        nm.totalnota as canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        0 acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm

                        
                        where nm.cancelado = 'SIM'

                union all

                select
                    0 vendabruta,
                    0 vendabrutanfce,
                    0 canceladas,
                    0 canceladasnfce,
                    coalesce((nm.desconto), 0) as descontos,
                    0 as descontosnfce,
                    0 acrescimos,
                    0 acrescimosnfce,
                    0 as recebimentos,
                    0 as taxaservico,
                    0 vendaliquida,
                    0 vendaliquidanfce,
                        cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm

                        where
                        nm.cancelado <> 'SIM'
                    and faturada = 'SIM'

                union all

                    select
                        0 vendabruta,
                        0 vendabrutanfce,
                        0 canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        coalesce((nm.outrosvalores), 0) as acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm
                        
                        where nm.cancelado <> 'SIM'
                        and faturada = 'SIM'

                union all

                select
                    0 vendabruta,
                    0 vendabrutanfce,
                    0 canceladas,
                    0 canceladasnfce,
                    0 as descontos,
                    0 as descontosnfce,
                    0 as acrescimos,
                    0 acrescimosnfce,
                    (valorentrada - valorsaida) as recebimentos,
                    0 as taxaservico,
                    0 vendaliquida ,
                    0 vendaliquidanfce,
                    Cast(datahoracadastro as date) data,
                    Cast(datahoracadastro as time) horario,
                    codfuncionario codfuncionario,
                    centrocusto centrocusto

                from tcaixa tca

                where
                    codreceber IS NOT NULL 
                     and (tca.origem not like '%SANGRIA%') AND (tca.origem not like '%SUPRIMENTO%')

                union all

                Select
                    0 vendabruta,
                    0 vendabrutanfce,
                    0 canceladas,
                    0 canceladasnfce,
                    0 as descontos,
                    0 as descontosnfce,
                    0 as acrescimos,
                    0 acrescimosnfce,
                    0 as recebimentos,
                    0 as taxaservico,
                    coalesce((nm.totalnota), 0) as vendaliquida,
                    0 vendaliquidanfce,
                    cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm
                        
                        where nm.cancelado <> 'SIM'
                        and faturada = 'SIM'
                        and nm.datafaturada is not null

                union all

                select
                        0 vendabruta,
                        nfce.valortotalnfce vendabrutanfce,
                        0 canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        0 acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nfce.dataemissao as date) data,
                        cast(nfce.horasaidaentrada as time) horario,
                        nfce.codoperador codfuncionario,
                        nfce.centrocusto centrocusto

                from tvendanfce nfce

                where nfce.dataemissao is not null

                union all

                select
                        0 vendabruta,
                        0 vendabrutanfce,
                        0 canceladas,
                        nfce.valortotalnfce as canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        0 acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nfce.dataehoracadastro as date) data,
                        cast(nfce.dataehoracadastro as time) horario,
                        nfce. codfuncionario,
                        nfce.centrocusto centrocusto

                from tvendanfce nfce

                        where nfce.dataehoracancelamento is not null
                        and nfce.inutilizada <> 'SIM'

                union all

                select
                        0 vendabruta,
                        0 vendabrutanfce,
                        0 canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        nfce.valordesconto descontosnfce,
                        0 acrescimos,
