                        0 vendabruta,
                        0 vendabrutanfce,
                        0 canceladas,
                        0 canceladasnfce,
                        0 as descontos,
                        0 as descontosnfce,
                        coalesce((nm.outrosvalores), 0) as acrescimos,
                        0 acrescimosnfce,
                        0 as recebimentos,
                        0 as taxaservico,
                        0 vendaliquida,
                        0 vendaliquidanfce,
                        cast(nm.dataehoracadastro as date) data,
                        cast(nm.dataehoracadastro as time) horario,
                        nm. codfuncionario,
                        nm.centrocusto centrocusto

                from tnotaconsumidor nm
                        
                        where nm.cancelado <> 'SIM'
                        and faturada = 'SIM'

                union all

                select
                    0 vendabruta,
                    0 vendabrutanfce,
                    0 canceladas,
                    0 canceladasnfce,
                    0 as descontos,
                    0 as descontosnfce,
                    0 as acrescimos,
