                        tca.codfuncionario codfuncionario,
                        tca.centrocusto centrocusto
                    from
                        tcaixa tca
                    where
                        origem = 'SUPRIMENTO NOTA MANUAL' or (origem = 'SUPRIMENTO NFCE')

                    union all

                    select
                        0 sangria,
                        0 suprimento,
                        (VALORSAIDA) as transferencia,
                        0 totalcaixa,
                        cast(datahoracadastro as date) data,
