select
                        especie,                                                
                        sum(total) total

                        from(
                            select
                                tca.especie especie,                                                
                                (cast(coalesce(tca.VALORENTRADA, 0) as float) - cast(coalesce(tca.VALORSAIDA, 0) as float)) as total,
                                cast(tca.datahoracadastro as date) data,
                                cast(tca.datahoracadastro as time) horario,
                                nm.codfuncionario codfuncionario,
                                tca.centrocusto centrocusto
                            from tcaixa tca
                            left join tnotaconsumidor nm
                            on tca.codmodulo = nm.contr
ole

                            where
                                 (tca.origem = 'NOTA CONSUMIDOR')                                 

                            union all

                            select
                                tca.especie especie,
                                (cast(coalesce(tca.VALORENTRADA, 0) as float) - cast(coalesce(tca.VALORSAIDA, 0) as float)) as total,
                                 cast(tca.datahoracadastro as date) data,
                                 cast(tca.datahoracadastro as time) horario,
                                 nfce.codoperador codfuncionario,
                                 tca.centrocusto centrocusto

                            from tcaixa tca
                            left join tvendanfce nfce
                            on tca.codnfce = nfce.controle

                            where
                                nfce.inutilizada is null
                                and (nfce.statusenvio = 'Emitida em contingÃªncia' or ((protocolo is not null) and (protocolo <> '')) )
                                and protocolocancelamento is null
                                and sat = 'NÃƒO'                                
                            )a

                                where data between '13.02.2025' and '13.02.2025'
                                
                                
                                
                                and total > 0

                            group by
                            especie
                            order by
                            total desc
